const SESSION_LENGTH = 10;
const MAX_STRESS = 100;

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

const shuffle = <T,>(items: T[]) => {
  const copy = [...items];
  for (let i = copy.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
};

function rankFor(score: number, resistance: number) {
  if (score >= 900 && resistance <= 1) return "S";
  if (score >= 760 && resistance <= 3) return "A";
  if (score >= 600) return "B";
  return "C";
}

export default function MaaIikaGame() {
  const [deck, setDeck] = useState<EventCard[]>([]);
  const [round, setRound] = useState(0);
  const [stress, setStress] = useState(18);
  const [resistance, setResistance] = useState(0);
  const [combo, setCombo] = useState(0);
  const [maxCombo, setMaxCombo] = useState(0);
  const [score, setScore] = useState(0);
  const [message, setMessage] = useState("起きたことを変えようとせず、次に使える反応を選ぶ。");
  const [flash, setFlash] = useState<ReactionKind | null>(null);
  const [startedAt, setStartedAt] = useState(0);
  const [finished, setFinished] = useState(false);
  const [best, setBest] = useState<string | null>(null);
  const [locked, setLocked] = useState(false);

  const current = deck[round];
  const progress = Math.round((round / SESSION_LENGTH) * 100);
  const options = current?.reactions ?? [];

  useEffect(() => {
    const saved = window.localStorage.getItem("maa-iika-best-rank");
    if (saved) setBest(saved);
  }, []);

  const start = () => {
    setDeck(
      shuffle(EVENTS)
        .slice(0, SESSION_LENGTH)
        .map((event) => ({ ...event, reactions: shuffle(event.reactions) })),
    );
    setRound(0);
    setStress(18);
    setResistance(0);
    setCombo(0);
    setMaxCombo(0);
    setScore(0);
    setMessage("予定外は止められない。引っかかる時間だけ短くできる。");
    setStartedAt(Date.now());
    setFinished(false);
    setFlash(null);
    setLocked(false);
  };

  useEffect(() => {
    if (deck.length === 0) start();
    // start only once after mount
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const finishSession = (nextScore: number, nextResistance: number) => {
    const nextRank = rankFor(nextScore, nextResistance);
    const order = ["C", "B", "A", "S"];
    const shouldSave = !best || order.indexOf(nextRank) > order.indexOf(best);
    if (shouldSave) {
      window.localStorage.setItem("maa-iika-best-rank", nextRank);
      setBest(nextRank);
    }
    setFinished(true);
  };

  const choose = (reaction: Reaction) => {
    if (!current || finished || locked) return;

    setFlash(reaction.kind);
    window.setTimeout(() => setFlash(null), 360);

    if (reaction.kind === "resist" || reaction.kind === "avoid") {
      const penalty = reaction.kind === "resist" ? 1 : 0;
      setResistance((value) => value + 1 + penalty);
      setStress((value) => clamp(value + reaction.stress, 0, MAX_STRESS));
      setCombo(0);
      setScore((value) => Math.max(0, value - (reaction.kind === "resist" ? 22 : 10)));
      setMessage(`${reaction.note}　出来事はまだここにある。`);
      return;
    }

    setLocked(true);
    const elapsed = Math.max(0, Date.now() - startedAt);
    const speedBonus = Math.max(0, 45 - Math.floor(elapsed / 1000));
    const nextCombo = combo + 1;
    setMaxCombo((value) => Math.max(value, nextCombo));
    const comboBonus = Math.min(45, nextCombo * 5);
    const gained = 70 + speedBonus + comboBonus + current.intensity * 8;
    const nextScore = score + gained;
    const nextResistance = resistance;

    setStress((value) => clamp(value + reaction.stress, 0, MAX_STRESS));
    setCombo(nextCombo);
    setScore(nextScore);
    setMessage(reaction.note);

    if (round + 1 >= SESSION_LENGTH) {
      finishSession(nextScore, nextResistance);
      return;
    }

    window.setTimeout(() => {
      setRound((value) => value + 1);
      setStartedAt(Date.now());
      setMessage("次の予定外。まず、起きたことをそのまま見る。");
      setLocked(false);
    }, 420);
  };

  const rank = rankFor(score, resistance);
  const caughtSeconds = resistance * 6;
  const acceptanceRate = Math.round(
    (SESSION_LENGTH / Math.max(SESSION_LENGTH, SESSION_LENGTH + resistance)) * 100,
  );

  if (!current && !finished) {
    return <main className={styles.page} />;
  }

  return (
    <main className={styles.page}>
      <div className={styles.ambient} aria-hidden="true">
        <span />
        <span />
        <span />
      </div>

      <header className={styles.header}>
        <a className={styles.back} href="/levelup" aria-label="LEVEL UPへ戻る">
          ← LEVEL UP
        </a>
        <div className={styles.logo}>まあ、いいか。</div>
        <div className={styles.best}>BEST {best ?? "—"}</div>
      </header>

      {!finished ? (
        <section className={styles.gameShell}>
          <div className={styles.hud}>
            <div className={styles.hudBlock}>
              <span>ROUND</span>
              <strong>{String(round + 1).padStart(2, "0")} / {SESSION_LENGTH}</strong>
            </div>
            <div className={styles.stressBlock}>
              <div className={styles.stressLabel}>
                <span>STRESS</span>
                <strong>{stress}</strong>
              </div>
              <div className={styles.stressTrack}>
                <i style={{ width: `${stress}%` }} />
              </div>
            </div>
            <div className={styles.hudBlock}>
              <span>FLOW</span>
              <strong>×{combo}</strong>
            </div>
          </div>

          <div className={styles.progressTrack} aria-hidden="true">
            <span style={{ width: `${progress}%` }} />
            <i style={{ left: `${progress}%` }}>●</i>
          </div>

          <section
            className={`${styles.eventCard} ${flash ? styles[`flash_${flash}`] : ""}`}
            aria-live="polite"
          >
            <div className={styles.sceneRow}>
              <span>{current.scene}</span>
              <div className={styles.intensity} aria-label={`強度 ${current.intensity}`}>
                {[1, 2, 3].map((value) => (
                  <i key={value} className={value <= current.intensity ? styles.on : ""} />
                ))}
              </div>
            </div>
            <div className={styles.icon} aria-hidden="true">{current.icon}</div>
            <p className={styles.unexpected}>予定外が起きた。</p>
            <h1>{current.event}</h1>
            <p className={styles.detail}>{current.detail}</p>

            <div className={styles.resistanceCloud} aria-hidden="true">
              <span>なんで？</span>
              <span>最悪</span>
              <span>こうなるはずだったのに</span>
            </div>
          </section>

          <div className={styles.message} role="status">{message}</div>

          <section className={styles.choices} aria-label="反応を選ぶ">
            <p>頭の中で、どれを採用する？</p>
            <div className={styles.choiceGrid}>
              {options.map((reaction) => (
                <button
                  type="button"
                  className={styles.choice}
                  key={reaction.label}
                  onClick={() => choose(reaction)}
                  disabled={locked}
                >
                  <span>{reaction.label}</span>
                  <i>→</i>
                </button>
              ))}
            </div>
          </section>

          <footer className={styles.tip}>
            <strong>RULE</strong>
            <span>抵抗するボタンは押せる。でも、ターンは進まない。</span>
          </footer>
        </section>
      ) : (
        <section className={styles.result}>
          <p className={styles.resultEyebrow}>SESSION COMPLETE</p>
          <div className={styles.rank}>{rank}</div>
          <h1>引っかかっても、戻ればいい。</h1>
          <p className={styles.resultLead}>
            ゴールは嫌なことが起きない人生ではなく、起きた後に操作権を取り戻すまでの時間を短くすること。
          </p>

          <div className={styles.resultGrid}>
            <div>
              <span>SCORE</span>
              <strong>{score}</strong>
            </div>
            <div>
              <span>引っかかり</span>
              <strong>{caughtSeconds}<small>秒相当</small></strong>
            </div>
            <div>
              <span>受容率</span>
              <strong>{acceptanceRate}<small>%</small></strong>
            </div>
            <div>
              <span>最大FLOW</span>
              <strong>×{maxCombo}</strong>
            </div>
          </div>

          <div className={styles.lesson}>
            <p>今日の一行</p>
            <strong>「そうなったか。」を、次の一手の前に置く。</strong>
            <span>受容は、我慢でも放置でもない。変えられない事実との綱引きを終えて、変えられる部分に戻ること。</span>
          </div>

          <div className={styles.resultActions}>
            <button type="button" onClick={start}>もう10回</button>
            <a href="/levelup">LEVEL UPへ戻る</a>
          </div>
        </section>
      )}
    </main>
  );
}

.page {
