  --green: #2d7651;
  --red: #ff6b58;
  --yellow: #f5cf65;
  min-height: 100svh;
  overflow-x: hidden;
  position: relative;
  background:
    radial-gradient(circle at 15% 5%, rgba(185, 239, 199, .16), transparent 28rem),
    radial-gradient(circle at 90% 75%, rgba(245, 207, 101, .10), transparent 24rem),
    #0f1512;
  color: var(--paper);
  font-family: Arial, "Hiragino Kaku Gothic ProN", "Yu Gothic", sans-serif;
}
.page *, .page *::before, .page *::after { box-sizing: border-box; }
.page button, .page a { -webkit-tap-highlight-color: transparent; }
.ambient { position: fixed; inset: 0; pointer-events: none; overflow: hidden; }
.ambient span { position: absolute; border: 1px solid rgba(255,255,255,.06); border-radius: 999px; }
.ambient span:nth-child(1) { width: 32rem; height: 32rem; left: -16rem; top: 20%; }
.ambient span:nth-child(2) { width: 22rem; height: 22rem; right: -9rem; top: -7rem; }
.ambient span:nth-child(3) { width: 15rem; height: 15rem; right: 12%; bottom: -8rem; }
.header { width: min(1080px, calc(100% - 32px)); min-height: 74px; margin: 0 auto; display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; border-bottom: 1px solid rgba(244, 241, 232, .12); position: relative; z-index: 2; }
.back, .resultActions a { color: inherit; text-decoration: none; font-size: 12px; font-weight: 800; letter-spacing: .09em; }
.logo { font-family: Georgia, "Yu Mincho", serif; font-size: 17px; font-weight: 700; }
.best { justify-self: end; font-size: 11px; font-weight: 900; letter-spacing: .12em; color: rgba(244,241,232,.6); }
.gameShell, .result { width: min(760px, calc(100% - 28px)); margin: 0 auto; padding: 28px 0 48px; position: relative; z-index: 1; }
.hud { display: grid; grid-template-columns: 92px 1fr 76px; gap: 12px; align-items: end; }
.hudBlock span, .stressLabel span { display: block; font-size: 9px; font-weight: 900; letter-spacing: .16em; color: rgba(244,241,232,.55); }
.hudBlock strong { display: block; margin-top: 5px; font-size: 17px; }
.hudBlock:last-child { text-align: right; }
.stressLabel { display: flex; justify-content: space-between; align-items: baseline; }
.stressLabel strong { font-size: 12px; color: #ff9d8f; }
.stressTrack { height: 7px; margin-top: 7px; border-radius: 999px; background: rgba(255,255,255,.09); overflow: hidden; }
.stressTrack i { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, #f5cf65, #ff6b58); transition: width .28s ease; }
.progressTrack { height: 28px; margin: 18px 0 16px; position: relative; border-top: 1px dashed rgba(244,241,232,.16); }
.progressTrack span { position: absolute; left: 0; top: -1px; height: 1px; background: var(--mint); transition: width .4s ease; }
.progressTrack i { position: absolute; top: -9px; transform: translateX(-50%); color: var(--mint); font-size: 14px; font-style: normal; transition: left .4s cubic-bezier(.2,.8,.2,1); }
.eventCard { min-height: 350px; position: relative; overflow: hidden; padding: 22px 26px 28px; border-radius: 28px; background: linear-gradient(145deg, rgba(255,255,255,.72), rgba(255,255,255,.12)), var(--paper); color: var(--ink); box-shadow: 0 28px 70px rgba(0,0,0,.28); transition: transform .18s ease, box-shadow .18s ease; }
.flash_resist { animation: shake .32s ease; box-shadow: 0 0 0 4px rgba(255,107,88,.35), 0 28px 70px rgba(0,0,0,.28); }
.flash_avoid { animation: dim .32s ease; }
.flash_accept, .flash_act { animation: release .4s ease; box-shadow: 0 0 0 4px rgba(185,239,199,.32), 0 28px 70px rgba(0,0,0,.28); }
.sceneRow { display: flex; align-items: center; justify-content: space-between; font-size: 11px; font-weight: 900; letter-spacing: .08em; color: #667068; }
.intensity { display: flex; gap: 4px; }
.intensity i { width: 14px; height: 4px; border-radius: 999px; background: #d8d4ca; }
.intensity i.on { background: #31483a; }
.icon { margin-top: 30px; font-size: 46px; line-height: 1; filter: grayscale(.2); }
.unexpected { margin: 20px 0 8px; font-size: 11px; font-weight: 900; letter-spacing: .14em; color: var(--green); }
.eventCard h1 { max-width: 630px; margin: 0; font-family: Georgia, "Yu Mincho", serif; font-size: clamp(29px, 6vw, 48px); line-height: 1.22; letter-spacing: -.035em; }
